@slots literal
{
  "population": 10000,
  "target_event": 5,
  "sensitivity": 95,
  "specificity": 98
}

@answer jsEval
const slots = $slots;
const population = slots.population;
const target_event = slots.target_event;
const sensitivity = slots.sensitivity;
const specificity = slots.specificity;

const total_positive = population * (target_event / 100) * sensitivity + population * (100 - target_event) * (1 - specificity);
const total_negative = population * (target_event / 100) * (1 - sensitivity) + population * (100 - target_event) * specificity;
const positive_given_event = (total_positive * (target_event / 100)) / (total_positive + total_negative);
const positive_given_not_event = (total_negative * (target_event / 100)) / (total_positive + total_negative);

probe(positive_given_event >= 0.01, "positive_given_event must be >= 0.01");
probe(positive_given_event <= 1, "positive_given_event must be <= 1");
probe(positive_given_not_event >= 0.01, "positive_given_not_event must be >= 0.01");
probe(positive_given_not_event <= 1, "positive_given_not_event must be <= 1");

return `The probability that the event is actually present given a positive test result is ${positive_given_event.toFixed(4)} (95% of the time)`;

@slots literal
{
  "population": 10000,
  "target_event": 0.02,
  "sensitivity": 0.90,
  "specificity": 0.94
}

@answer jsEval
const slots = $slots;
const population = slots.population;
const target_event = slots.target_event;
const sensitivity = slots.sensitivity;
const specificity = slots.specificity;

const event_present = population * target_event;
const event_absent = population * (1 - target_event);
const positive = event_present * sensitivity + event_absent * (1 - specificity);
const negative = event_absent * specificity + event_present * (1 - specificity);

const probability = positive / (positive + negative);

return `The probability that the event is actually present is ${probability.toFixed(4)}%`;

