const population = slots.population;
const target_event = slots.target_event;
const sensitivity = slots.sensitivity;
const specificity = slots.specificity;

const true_positive = population * target_event * sensitivity;
const false_positive = population * (1 - target_event) * (1 - specificity);
const true_negative = population * (1 - target_event) * specificity;
const false_negative = population * target_event * (1 - sensitivity);

const total_positive = true_positive + false_positive;
const positive_prob = true_positive / total_positive;

probe(positive_prob >= 0.01, "positive_prob is less than 0.01");
probe(positive_prob <= 0.99, "positive_prob is more than 0.99");
