@answer jsEval
const slots = $slots;
const field_activities = slots.field_activities;
const completion_limit = slots.completion_limit;
const block_rate = slots.block_rate;
const block_time = slots.block_time;
const setup_time = slots.setup_time;
const staffing = slots.staffing;

const total_block_time = (field_activities / block_rate) * block_time;
const total_setup_time = setup_time;
const total_time = total_block_time + total_setup_time;

const is_within_limit = total_time <= completion_limit;

return is_within_limit ? "Yes" : "No";

