  }
}

@answer jsEval
const slots = $slots;
const start = slots.start;
const step = slots.step;
const subtract = slots.subtract;
const repeat = slots.repeat;

const sequence = [start];
let current = start;
let i = 0;

while (i < repeat) {
  current += step;
  sequence.push(current);
  current -= subtract;
  sequence.push(current);
  i++;
}

return sequence;

