@answer jsEval
const slots = $slots;
const shortest = slots.routes.find((route) => route.length === slots.routes.reduce((min, current) => (current.length < min.length ? current : min), slots.routes[0]));
const longest = slots.routes.find((route) => route.length === slots.routes.reduce((max, current) => (current.length > max.length ? current : max), slots.routes[0]));
const difference = longest.length - shortest.length;
return `The shortest route is ${shortest.name} and it is ${difference} meters shorter than the longest route.`;

