const move = slots.move;
const end = slots.end;
const startSplit = start.split(",");
const moveSplit = move.split(",");
const endSplit = end.split(",");
const startRow = parseInt(startSplit[0]);
const startCol = parseInt(startSplit[1]);
const moveRow = parseInt(moveSplit[0]);
const moveCol = parseInt(moveSplit[1]);
const endRow = parseInt(endSplit[0]);
const endCol = parseInt(endSplit[1]);
const row = startRow + moveRow;
const col = startCol + moveCol;
const rowCheck = row === endRow;
const colCheck = col === endCol;
if (rowCheck && colCheck) {
  return "It ends at " + end;
} else {
  return "It ends at " + (row + ", " + col);
}

