const slots = $slots;
const start = slots.start;
const regeneration = slots.regeneration;
const users = slots.users;
const harvest_per_user = slots.harvest_per_user;
const minimum_stock = slots.minimum_stock;
const stock = slots.stock;

const end_stock = start + regeneration - users * harvest_per_user;
const total_harvest = users * harvest_per_user;
const is_non_depleting = end_stock >= minimum_stock;
const per_user_harvest = regeneration / users;

return {
  "end_stock": end_stock,
  "is_non_depleting": is_non_depleting,
  "per_user_harvest": per_user_harvest
};
